#include <stdio.h>
double repeated_power(double base, int exponent);
int main(void) {
    double base = 0.0;
    int exponent = 0;
    while (scanf("%lf", &base) == 1) {
        if (scanf("%d", &exponent) != 1) return 1;
        if (exponent < 0 || exponent > 8) return 1;
        double answer = repeated_power(base, exponent);
        printf("%.2f\n", answer);
    }
    return 0;
}
double repeated_power(double base, int exponent) {
    double product = 1.0;
    for (int done = 0; done < exponent; done++) {
        product *= base;
    }
    return product;
}

